import { useEffect, useRef, useState, type FormEvent } from 'react';
import { JxStepper, JxInputField, JxButton } from '@jinx-ui/react';

type SignupValues = {
  name: string;
  email: string;
  city: string;
  street: string;
  zip: string;
};

type SignupWizardProps = {
  onSubmit: (values: SignupValues) => void;
};

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const LAST_STEP = STEPS.length - 1;

const EMPTY_VALUES: SignupValues = { name: '', email: '', city: '', street: '', zip: '' };

function validateStep(step: number, values: SignupValues) {
  const errors: Partial<Record<keyof SignupValues, string>> = {};
  if (step === 0) {
    if (!values.name.trim()) errors.name = 'Укажите имя, оно попадёт в письма';
    if (!values.email.includes('@')) errors.email = 'Укажите адрес с символом @';
  }
  if (step === 1) {
    if (!values.city.trim()) errors.city = 'Укажите город';
    if (!values.street.trim()) errors.street = 'Укажите улицу и номер дома';
  }
  return errors;
}

export default function SignupWizard({ onSubmit }: SignupWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<SignupValues>(EMPTY_VALUES);
  const [showErrors, setShowErrors] = useState(false);
  const panelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    panelRef.current?.focus();
  }, [step]);

  const errors = showErrors ? validateStep(step, values) : {};

  const setField = (field: keyof SignupValues) => (event: { target: { value: string } }) =>
    setValues((previous) => ({ ...previous, [field]: event.target.value }));

  const goBack = () => {
    setShowErrors(false);
    setStep((previous) => Math.max(previous - 1, 0));
  };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (Object.keys(validateStep(step, values)).length > 0) {
      setShowErrors(true);
      return;
    }
    setShowErrors(false);
    if (step < LAST_STEP) {
      setStep(step + 1);
      return;
    }
    onSubmit(values);
  };

  const review: Array<{ term: string; value: string }> = [
    { term: 'Имя', value: values.name },
    { term: 'Почта', value: values.email },
    { term: 'Город', value: values.city },
    { term: 'Улица и дом', value: values.street },
    { term: 'Индекс', value: values.zip.trim() || 'не указан' },
  ];

  return (
    <form
      noValidate
      onSubmit={handleSubmit}
      style={{ display: 'flex', flexDirection: 'column', gap: '24px', fontFamily: 'var(--jx-font-sans)' }}
    >
      <JxStepper steps={STEPS} current={step} />

      <div
        ref={panelRef}
        tabIndex={-1}
        role="group"
        aria-label={`Шаг ${step + 1} из ${STEPS.length}: ${STEPS[step].label}`}
        style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}
      >
        {step === 0 && (
          <>
            <JxInputField
              label="Имя"
              name="name"
              autoComplete="given-name"
              required
              value={values.name}
              onChange={setField('name')}
              errorText={errors.name}
            />
            <JxInputField
              label="Электронная почта"
              name="email"
              type="email"
              autoComplete="email"
              required
              value={values.email}
              onChange={setField('email')}
              errorText={errors.email}
              helperText="На этот адрес придёт письмо для подтверждения"
            />
          </>
        )}

        {step === 1 && (
          <>
            <JxInputField
              label="Город"
              name="city"
              autoComplete="address-level2"
              required
              value={values.city}
              onChange={setField('city')}
              errorText={errors.city}
            />
            <JxInputField
              label="Улица и дом"
              name="street"
              autoComplete="street-address"
              required
              value={values.street}
              onChange={setField('street')}
              errorText={errors.street}
            />
            <JxInputField
              label="Почтовый индекс"
              name="zip"
              inputMode="numeric"
              autoComplete="postal-code"
              value={values.zip}
              onChange={setField('zip')}
              helperText="Необязательно, ускоряет доставку"
            />
          </>
        )}

        {step === 2 && (
          <dl
            style={{
              display: 'grid',
              gridTemplateColumns: 'minmax(120px, auto) 1fr',
              gap: '12px 16px',
              margin: 0,
              padding: '16px',
              background: 'var(--jx-surface)',
              border: '1px solid var(--jx-border)',
              borderRadius: 'var(--jx-r)',
            }}
          >
            {review.map((row) => (
              <div key={row.term} style={{ display: 'contents' }}>
                <dt style={{ color: 'var(--jx-text-2)' }}>{row.term}</dt>
                <dd style={{ margin: 0, color: 'var(--jx-text)', overflowWrap: 'anywhere' }}>{row.value}</dd>
              </div>
            ))}
          </dl>
        )}
      </div>

      <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
        <JxButton variant="ghost" type="button" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        <JxButton variant="primary" type="submit">
          {step === LAST_STEP ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

